import React, { useState } from "react";
import AchievementsPanel from "./AchievementsPanel";
import UserProfileCard from './UserProfileCard';

export default function AdminDashboard({ reports, token, setMsg, admin }) {
  const [ngos, setNgos] = useState(null);
  const [events, setEvents] = useState(null);
  const [eventStats, setEventStats] = useState(null);
  const [mostActive, setMostActive] = useState(null);

  const API = process.env.REACT_APP_API || "http://localhost:4000";
  //  Clears all sections
  const clearAll = () => {
    setNgos(null);
    setEvents(null);
    setEventStats(null);
    setMostActive(null);
  };
  const loadData = async (endpoint, setter, expectedField = null, errMsg = "Failed to load") => {
    if (!token) return setMsg("Login as admin first");

    clearAll();

    try {
      const res = await fetch(`${API}${endpoint}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        // try to parse JSON error message
        let txt = await res.text();
        try {
          const j = JSON.parse(txt);
          throw new Error(j.message || errMsg);
        } catch {
          throw new Error(errMsg);
        }
      }

      const data = await res.json();

      // If expectedField is provided and exists on response, use it
      if (expectedField && (data[expectedField] !== undefined && data[expectedField] !== null)) {
        setter(data[expectedField]);
        return;
      }

      // Flexible fallbacks for common shapes from your backend
      // prefer arrays/lists or single objects
      const fallbackCandidates = [
        "top",
        "mostActive",
        "most",
        "badges",
        "ngos",
        "events",
        "volunteers",
        "donors",
        "results",
        "participants",
        "donations",
        "user_badges",
      ];

      for (const key of fallbackCandidates) {
        if (data[key] !== undefined && data[key] !== null) {
          setter(data[key]);
          return;
        }
      }

      // If server returned an array directly
      if (Array.isArray(data)) {
        setter(data);
        return;
      }

      // If server returned an object that isn't an array, pass it through
      setter(data);
    } catch (err) {
      console.error(err);
      setMsg(err.message || errMsg);
    }
  };

  // NEW: Most Active NGO fetch (made tolerant to various response shapes)
  const loadMostActive = async () => {
    if (!token) return setMsg("Login as admin first");

    clearAll();

    try {
      const res = await fetch(`${API}/api/actions/most-active-ngo`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        let txt = await res.text();
        try {
          const j = JSON.parse(txt);
          throw new Error(j.message || "Failed to load most active NGO");
        } catch {
          throw new Error("Failed to load most active NGO");
        }
      }

      const data = await res.json();

      // backend returns { mostActive: result || null } in file you provided
      const candidate = data.mostActive || data.most || data.top || data.most_active || data[0] || null;

      // If candidate is an array or object, normalize
      if (Array.isArray(candidate)) {
        setMostActive(candidate[0] || null);
      } else {
        setMostActive(candidate || null);
      }
    } catch (err) {
      console.error(err);
      setMsg(err.message || "Failed to load most active NGO");
    }
  };

  const deleteNgo = async (id) => {
    if (!token) return setMsg("Login as admin first");
    if (!window.confirm("Are you sure you want to remove this NGO?")) return;

    try {
      const res = await fetch(`${API}/api/actions/remove-ngo/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        let txt = await res.text();
        try {
          const j = JSON.parse(txt);
          throw new Error(j.message || "Failed to delete NGO");
        } catch {
          throw new Error("Failed to delete NGO");
        }
      }

      setMsg("NGO removed successfully");
      // Remove from local state safely
      setNgos((prev) => (Array.isArray(prev) ? prev.filter((n) => n.id !== id) : prev));
    } catch (err) {
      console.error(err);
      setMsg(err.message);
    }
  };

  // Helper render for "eventStats" / generic results (works for volunteers, donors, badges, events)
  const renderResults = (results) => {
    if (!results) return null;

    // If backend returned an object (single), wrap into array for rendering
    const list = Array.isArray(results) ? results : [results];

    if (!list.length) return <p>No data found.</p>;

    return list.map((item, i) => {
      // Event-like item
      if (item.title || item.event_title) {
        const title = item.title || item.event_title;
        const date = item.date || item.created_at || item.event_date;
        return (
          <div
            key={item.id || i}
            style={{
              padding: 8,
              background: "#fff",
              borderRadius: 8,
              marginBottom: 8,
            }}
          >
            <strong>{title}</strong>
            {date && <div style={{ fontSize: 13, color: "#666" }}>{date}</div>}
            {item.volunteers_count !== undefined && (
              <div style={{ fontSize: 13 }}>Volunteers: {item.volunteers_count}</div>
            )}
            {item.donations_sum !== undefined && (
              <div style={{ fontSize: 13 }}>Donations: ₹{item.donations_sum}</div>
            )}
          </div>
        );
      }

      // Volunteer / Donor / User-like item
      if (item.name || item.user_name || item.donor_name || item.email) {
        const name = item.name || item.user_name || item.donor_name || item.email;
        return (
          <div
            key={item.id || i}
            style={{
              padding: 10,
              background: "#fff",
              borderRadius: 8,
              marginBottom: 8,
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <div>
              <strong>{name}</strong>
              {item.email && <div style={{ fontSize: 13, color: "#666" }}>{item.email}</div>}
              {item.amount !== undefined && <div style={{ fontSize: 13 }}>Amount: ₹{item.amount}</div>}
              {item.points !== undefined && <div style={{ fontSize: 13 }}>Points: {item.points}</div>}
            </div>
            {/* small meta */}
            <div style={{ fontSize: 12, color: "#666", textAlign: "right" }}>
              {item.created_at && <div>{new Date(item.created_at).toLocaleString()}</div>}
              {item.id && <div>ID: {item.id}</div>}
            </div>
          </div>
        );
      }

      // Badge-like item
      if (item.title && item.description) {
        return (
          <div
            key={item.key || i}
            style={{
              padding: 10,
              background: "#fff",
              borderRadius: 8,
              marginBottom: 8,
            }}
          >
            <strong>{item.title}</strong>
            <div style={{ fontSize: 13, color: "#666" }}>{item.description || item.desc}</div>
            {item.key && <div style={{ fontSize: 12, color: "#666" }}>Key: {item.key}</div>}
          </div>
        );
      }

      // Fallback generic display of object
      return (
        <div
          key={i}
          style={{
            padding: 10,
            background: "#fff",
            borderRadius: 8,
            marginBottom: 8,
            wordBreak: "break-word",
          }}
        >
          <pre style={{ margin: 0, whiteSpace: "pre-wrap" }}>{JSON.stringify(item, null, 2)}</pre>
        </div>
      );
    });
  };

  return (
    <div style={{ display: "flex", gap: 16, alignItems: "flex-start" }}>
      {/* LEFT PANEL */}
      <div style={{ flex: 1 }}>

        {/* ⭐ NEW PROFILE HEADER ⭐ */}
        <div
          style={{
            background: "#fff",
            padding: "14px 16px",
            borderRadius: 12,
            marginBottom: 16,
            boxShadow: "0 6px 20px rgba(2,6,23,0.05)",
            display: "flex",
            alignItems: "center",
            gap: 12,
          }}
        >
          <div
            style={{
              width: 48,
              height: 48,
              borderRadius: "50%",
              background: "#ececec",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              fontSize: 22,
              fontWeight: 600,
              color: "#333",
            }}
          >
            👤
          </div>

          <div>
            <div style={{ fontWeight: 600, fontSize: 16 }}>
              {admin?.email || "admin@ngo.local"}
            </div>
            <div style={{ fontSize: 13, color: "#666" }}>Role: Admin</div>
          </div>
        </div>

        <AchievementsPanel
          token={token}
          me={{ points: reports?.adminPoints || 0 }}
          role="user"
          setMsg={setMsg}
        />

        <h3>Admin Reports</h3>

        <div className="cards">
          <div className="stat-card">
            <div className="stat-num">
              {reports?.donations
                ? reports.donations.reduce(
                    (sum, d) => sum + parseFloat(d.amount || 0),
                    0
                  )
                : "-"}
            </div>
            <div className="stat-label">Total Donation Amount (₹)</div>
          </div>

          <div className="stat-card">
            <div className="stat-num">{reports?.volunteers?.length || 0}</div>
            <div className="stat-label">Total Volunteers</div>
          </div>

          <div className="stat-card">
            <div className="stat-num">{reports?.feedbacks?.length || 0}</div>
            <div className="stat-label">Feedbacks</div>
          </div>
        </div>

        {/* ACTION BUTTONS */}
        <div style={{ marginTop: 12 }}>
          <button
            onClick={() =>
              loadData("/api/actions/ngos", setNgos, "ngos", "Failed to load NGOs")
            }
          >
            View Registered NGOs
          </button>

          <button
            style={{ marginLeft: 8 }}
            onClick={() =>
              loadData(
                "/api/actions/registered-events",
                setEvents,
                "events",
                "Failed to load events"
              )
            }
          >
            View Registered Events
          </button>

          <button
            style={{ marginLeft: 8 }}
            onClick={() =>
              loadData(
                "/api/actions/event-stats",
                setEventStats,
                "events",
                "Failed to load event stats"
              )
            }
          >
            View Event Stats
          </button>
        </div>

        {/* EVENT LIST */}
        {events && (
          <div style={{ marginTop: 20 }}>
            <h4>Registered Events</h4>
            {Array.isArray(events) && events.length ? (
              events.map((e) => (
                <div
                  key={e.id}
                  style={{
                    padding: 8,
                    background: "#fff",
                    borderRadius: 8,
                    marginBottom: 8,
                  }}
                >
                  <strong>{e.title}</strong>
                  <div style={{ fontSize: 13, color: "#666" }}>{e.date || e.created_at}</div>
                </div>
              ))
            ) : (
              <p>No events registered.</p>
            )}
          </div>
        )}

        {/* EVENT STATS */}
        {eventStats && (
          <div style={{ marginTop: 20 }}>
            <h4>Results</h4>
            {renderResults(eventStats)}
          </div>
        )}

        {/* NGO LIST */}
        {ngos && (
          <div style={{ marginTop: 20 }}>
            <h4>Registered NGOs</h4>
            {Array.isArray(ngos) && ngos.length ? (
              ngos.map((n) => (
                <div
                  key={n.id}
                  style={{
                    padding: 8,
                    background: "#fff",
                    borderRadius: 8,
                    marginBottom: 8,
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                  }}
                >
                  <div>
                    <strong>{n.name}</strong>
                    <div style={{ fontSize: 13, color: "#666" }}>{n.email}</div>
                  </div>

                  <button
                    style={{
                      padding: "6px 12px",
                      background: "red",
                      color: "white",
                      border: "none",
                      borderRadius: 6,
                      cursor: "pointer",
                    }}
                    onClick={() => deleteNgo(n.id)}
                  >
                    Remove
                  </button>
                </div>
              ))
            ) : (
              <p>No NGOs registered.</p>
            )}
          </div>
        )}

      </div>

      {/* RIGHT PANEL */}
<div
  style={{
    width: 280,
    flexShrink: 0,
    position: "sticky",
    top: 16,
    display: "flex",
    flexDirection: "column",
    gap: 16,
  }}
>
  {/* Quick Actions with yellow border */}
  <div
    style={{
      background: "#FFFBEA", // Light yellow background
      padding: 12,
      borderRadius: 10,
      border: "2px solid #FFD700", // Gold border
      boxShadow: "0 6px 20px rgba(2,6,23,0.04)",
    }}
  >
    <h4>Quick Actions</h4>

    <button
      onClick={() =>
        loadData(
          "/api/actions/top-volunteers",
          setEventStats,
          "top",
          "Failed to load top volunteers"
        )
      }
      style={{ width: "100%", padding: 10, borderRadius: 8, marginBottom: 8 }}
    >
      Top Volunteers
    </button>

    <button
      onClick={() =>
        loadData(
          "/api/actions/top-donors",
          setEventStats,
          "top",
          "Failed to load top donors"
        )
      }
      style={{ width: "100%", padding: 10, borderRadius: 8, marginBottom: 8 }}
    >
      Top Donors
    </button>

    <button
      onClick={() =>
        loadData(
          "/api/actions/badges",
          setEventStats,
          "badges",
          "Failed to load badges"
        )
      }
      style={{ width: "100%", padding: 10, borderRadius: 8 }}
    >
      View Badges
    </button>
  </div>

  {/* Most Active NGO with yellow border */}
  <div
    style={{
      background: "#FFFBEA", // Light yellow background
      padding: 12,
      borderRadius: 10,
      border: "2px solid #FFD700", // Gold border
      boxShadow: "0 6px 20px rgba(2,6,23,0.04)",
    }}
  >
    <h4>Most Active NGO</h4>

    <button
      onClick={loadMostActive}
      style={{ marginTop: 8, padding: 8, width: "100%", borderRadius: 6 }}
    >
      Load Most Active NGO
    </button>

    {mostActive && (
      <div style={{ marginTop: 12 }}>
        <strong>{mostActive.name}</strong>
        <div style={{ fontSize: 13, color: "#666" }}>
          Activity Score: {(mostActive?.activity_score ?? mostActive?.activityScore ?? mostActive?.activity) ?? "N/A"}
        </div>
      </div>
    )}
  </div>
</div>

    </div>
  );
}
